function DET_INT(A):
  M <- copy of A as exact rationals;  det <- 1
  for col in 0..n-1:
    find pivot row r >= col with M[r][col] != 0
    if none: return 0
    if r != col: swap rows; det <- -det
    det <- det * M[col][col]
    for r in col+1..n-1:
      f <- M[r][col] / M[col][col]
      M[r] <- M[r] - f * M[col]
  return det

function IS_UNIMODULAR(G):
  return DET_INT(G) in {+1, -1}

