function DONALDSON_OBSTRUCTION(G):
  n <- size(G)
  if n == 0: return False        # rank 0 is trivially standard
  for i in 0..n-1:
    if G[i][i] is odd: return False   # form is odd, no obstruction
  return True                    # even + positive rank => obstructed
